<script setup>
import { onMounted, onBeforeUnmount, ref } from 'vue'
import { gsap } from '../gsap'
// Both generated by scripts/split-logo.mjs, same viewBox so they stack exactly.
import letters from '../assets/logo-letters.svg?raw'
import rootsUrl from '../assets/logo-roots.svg'

defineProps({ blok: Object })

const root = ref()
let ctx

onMounted(() => {
  ctx = gsap.context(() => {
    const mm = gsap.matchMedia()
    mm.add('(prefers-reduced-motion: no-preference)', () => {
      gsap
        .timeline()
        .from('.logo__letter', {
          opacity: 0,
          y: 20,
          duration: 1.4,
          stagger: { each: 0.08, from: 'random' },
          ease: 'power2.out',
        })
        // Roots sprout from the letters outward: a band centered on the letters opens up and down.
        .from('.hero__roots', { '--reveal': '0%', duration: 2.6, ease: 'power2.out' }, 0.5)

      gsap.to('.hero__inner', {
        yPercent: 25,
        opacity: 0.2,
        ease: 'none',
        scrollTrigger: { trigger: root.value, start: 'top top', end: 'bottom top', scrub: true },
      })
    })
  }, root.value)
})

onBeforeUnmount(() => ctx?.revert())
</script>

<template>
  <header ref="root" class="hero">
    <h1 class="hero__inner">
      <span class="sr-only">Loyck Tattoo</span>
      <span class="hero__art">
        <span class="hero__letters" v-html="letters"></span>
        <img class="hero__roots" :src="rootsUrl" alt="" />
      </span>
    </h1>
  </header>
</template>

<style scoped>
.hero {
  overflow: hidden;
}

/* Mockup scale: the lockup is wider than the viewport and cropped by the edges. */
.hero__art {
  position: relative;
  display: block;
  width: 110vw;
  margin: -5.4vw 0 0 -5vw;
  color: var(--bone);
}

.hero__letters :deep(svg) {
  display: block;
  width: 100%;
  height: auto;
}

.hero__roots {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  /* --mid: letters' centerline (printed by split-logo.mjs). --reveal: half-height of the visible band. */
  --mid: 51.6%;
  --reveal: 60%;
  --edge: 6%;
  mask-image: linear-gradient(
    to bottom,
    transparent calc(var(--mid) - var(--reveal) - var(--edge)),
    #000 calc(var(--mid) - var(--reveal)),
    #000 calc(var(--mid) + var(--reveal)),
    transparent calc(var(--mid) + var(--reveal) + var(--edge))
  );
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
}
</style>
